(()=>{const L=Lab;
 L.modes.E={name:'排查队列',purpose:'一次聚焦一个判断，保留其他未完成原因作为队列。',headline:'先处理哪一项',render:()=>{
  const t=L.task(L.state.focus),all=L.deps(t),pending=L.open(t),done=all.filter(d=>d.status==='已完成');
  return `<div class="guided"><section class="question"><span class="eyebrow">// CURRENT QUESTION</span><h2>${pending.length?'要继续这项工作，还需要什么？':t.reason?'没有下级前置，为什么仍然阻塞？':'这条路径已经查到末端。'}</h2><p class="question-task">${L.esc(t.title)}</p><div class="guided-facts">${L.badge(t)}<span>${pending.length} 项前置未完成</span></div>${t.reason?`<div class="reason"><b>记录的原因</b><p>${L.esc(t.reason)}</p></div>`:''}<div class="next-note"><span class="eyebrow">接下来可以</span><p>${pending.length?'从原因队列选择一项，继续向前追踪。':t.reason?'核对等待条件，或返回原任务看其他原因。':'核对预期产出，或返回原任务继续排查。'}</p><button data-act="origin">回到原任务看全局</button></div><p class="output"><small>当前工作的预期产出</small>${L.esc(t.output)}</p></section><section class="queue"><div class="section-title"><h3>未完成原因队列</h3><span>${pending.length} 项</span></div>${pending.map((d,i)=>`<div class="queue-item"><span class="queue-index">${i+1}</span><div><span class="code">${d.code} / ${L.project(d.project)}</span><h3>${L.esc(d.title)}</h3><p>${d.reason?L.esc(d.reason):d.missing?'引用缺失，不能忽略。':L.open(d).length?`下级还有 ${L.open(d).length} 项未完成。`:'等待这项工作本身完成。'}</p>${L.badge(d)}<button data-act="focus" data-id="${d.id}" ${d.missing?'disabled':''}>${d.missing?'无法进入':'检查这一项 →'}</button></div></div>`).join('')}${!pending.length?'<p class="quiet">没有未完成的前置。人工阻塞仍需单独判断。</p>':''}${!L.state.hideDone&&done.length?`<details class="completed"><summary>已满足的前置 ${done.length} 项</summary>${done.map(d=>L.button(d.id)).join('')}</details>`:''}<p class="queue-warning">${L.state.hideDone?'已完成项已隐藏。':''}队列按数据顺序排列，不代表优先级。已查看不等于已解决。</p></section></div>`;
 }};
 L.modes.F={name:'依赖矩阵',purpose:'横向比较任务与共同前置，逐格核对关系与状态。',headline:'把关系放在同一张表',render:()=>{
  const rows=L.visible(),ids=[...new Set(rows.flatMap(t=>t.deps))],cols=ids.map(L.task).filter(d=>!L.state.hideDone||d.status!=='已完成');
  return `<div class="matrix-caption"><h2>谁需要谁</h2><p>每行是任务，每列是前置；只有有关系的单元格可进入。显示 ${cols.length} / 全部 ${ids.length} 个前置。</p></div><div class="matrix-scroll"><table class="matrix"><caption class="sr-only">行任务需要列前置完成，勾号表示该前置已完成</caption><thead><tr><th scope="col">任务需要 →</th>${cols.map(d=>`<th scope="col"><button data-act="focus" data-id="${d.id}" ${d.missing?'disabled':''}><span>${d.code}</span>${L.esc(d.title)}</button></th>`).join('')}</tr></thead><tbody>${rows.map(t=>`<tr class="${t.id===L.state.focus?'active-row':''}"><th scope="row"><button data-act="origin" data-id="${t.id}"><span>${t.code}</span>${L.esc(t.title)}</button></th>${cols.map(d=>`<td>${t.deps.includes(d.id)?`<button data-act="focus" data-id="${d.id}" ${d.missing?'disabled':''} aria-label="${L.esc(t.title)}需要${L.esc(d.title)}，${d.status}">${d.missing?'? 缺失':d.status==='已完成'?'✓ 满足':'● 未完成'}</button>`:'<span aria-label="无直接前置关系">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="quiet">没有匹配任务，当前查看对象仍保留。</p>':''}<div class="matrix-focus"><span class="eyebrow">// CURRENT OBJECT</span>${L.details(L.task(L.state.focus))}</div>`;
 }};
})();
